const b = $input.first().json.body || {};
const d = b.datos || {};

// Idempotencia: si GitHub reintenta el mismo aviso, no se manda dos veces.
const sd = $getWorkflowStaticData('global');
sd.vistos = sd.vistos || [];
if (b.evento_id && sd.vistos.includes(b.evento_id)) return [];
if (b.evento_id) sd.vistos = [...sd.vistos, b.evento_id].slice(-300);

const ok = d.resultado === 'success';
const liberadas = Number(d.liberadas || 0);
const revisadas = Number(d.revisadas || 0);
const runUrl = String(d.run_url || '');

const texto = ok
  ? `🧹 *Pedidos vencidos liberados*\n\nSe liberaron *${liberadas}* de *${revisadas}* pedidos revisados y el stock volvió a la tienda.`
  : `⚠️ *Falló el liberador de pedidos*\n\nEl workflow no pudo completar la limpieza. Revisá GitHub Actions:${runUrl ? `\n${runUrl}` : ''}`;

return [{ json: { to_phone: '5493875029222', texto } }];
